UPDATE task
SET status = #{toStatus}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE task
SET
    status = #{toStatus},
    retry_count = #{newRetryCount},
    last_error_message = NULL
WHERE id = #{id}
  AND status = #{fromStatus}
  AND retry_count = #{oldRetryCount}

UPDATE task
SET
    status = #{toStatus},
    last_error_message = #{lastErrorMessage}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE task
SET
    status = #{toStatus},
    last_error_message = NULL
WHERE id = #{id}
    AND status = #{fromStatus}

